script.script:
import jenkins.*
import jenkins.model.*
import hudson.*
import hudson.model.*
import groovy.json.JsonSlurper;

def buildSpec = new JsonSlurper().parse(new File('/var/jenkins_home/workspace/Check For Updates/build-spec.json'));

def releaseControlCommit = build.getEnvironment(listener).get("GIT_COMMIT")
if (!(releaseControlCommit ==~ /[0-9a-f]{40}/)) {
    throw new Exception("Check For Updates requires an exact release-control commit, got: ${releaseControlCommit}")
}

def migrationsRun = Jenkins.instance.getItemByFullName("PIC-SURE Database Migrations")
    .scheduleBuild2(0, new ParametersAction(
        new StringParameterValue("release_control_commit", releaseControlCommit)
    )).get()
if (migrationsRun.result != Result.SUCCESS) {
    throw new Exception("PIC-SURE Database Migrations failed with result: ${migrationsRun.result}")
}

def pipelineRun = Jenkins.instance.getItemByFullName("PIC-SURE Pipeline")
    .scheduleBuild2(0, new ParametersAction(
        new StringParameterValue("release_control_commit", releaseControlCommit)
    )).get()
if (pipelineRun.result != Result.SUCCESS) {
    throw new Exception("PIC-SURE Pipeline failed with result: ${pipelineRun.result}")
}

import jenkins.*
import jenkins.model.*
import hudson.*
import hudson.model.*
import groovy.json.JsonSlurper;

def envVars= Hudson.instance.getItem("Check For Updates").lastBuild.properties.get("envVars");
